import sys
import re

def main():
    text = sys.stdin.read()
    env = {}
    # Matches an assignment: identifier <- (identifier | integer) ;
    pat = re.compile(r'^\s*([A-Za-z_]\w*)\s*<-\s*([A-Za-z_]\w*|[-+]?\d+)\s*;?\s*$')
    for raw in text.splitlines():
        line = raw.split('//', 1)[0].strip()
        if not line:
            continue
        # A line might contain several statements separated by ';'
        for stmt in line.split(';'):
            stmt = stmt.strip()
            if not stmt:
                continue
            m = pat.match(stmt + ';')
            if not m:
                continue
            target, src = m.group(1), m.group(2)
            if re.fullmatch(r'[-+]?\d+', src):
                val = int(src)
            else:
                val = env.get(src)
            env[target] = val
    def fmt(v):
        return str(v) if v is not None else "None"
    print("a ?= {}; b ?= {}; TMP ?= {};".format(
        fmt(env.get('a')), fmt(env.get('b')), fmt(env.get('TMP'))))

if __name__ == "__main__":
    main()
